import{_ as o,o as n,c as r,ah as s}from"./chunks/framework.DjU4PSOm.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"지향성이란","slug":"지향성이란","link":"#지향성이란","children":[]},{"level":2,"title":"지향성의 역설","slug":"지향성의-역설","link":"#지향성의-역설","children":[]},{"level":2,"title":"명제적 태도","slug":"명제적-태도","link":"#명제적-태도","children":[]},{"level":2,"title":"명제적 태도와 \\"수적 태도\\" — 신비감의 완화","slug":"명제적-태도와-수적-태도-—-신비감의-완화","link":"#명제적-태도와-수적-태도-—-신비감의-완화","children":[]},{"level":2,"title":"사유의 언어 가설 (포더)","slug":"사유의-언어-가설-포더","link":"#사유의-언어-가설-포더","children":[]},{"level":2,"title":"데닛의 세 가지 예측 전략과 지향적 태도","slug":"데닛의-세-가지-예측-전략과-지향적-태도","link":"#데닛의-세-가지-예측-전략과-지향적-태도","children":[]},{"level":2,"title":"지향적 체계로서의 마음 — 도구주의 논쟁","slug":"지향적-체계로서의-마음-—-도구주의-논쟁","link":"#지향적-체계로서의-마음-—-도구주의-논쟁","children":[]},{"level":2,"title":"좁은 내용과 넓은 내용 — 지향적 태도에 대한 외재론","slug":"좁은-내용과-넓은-내용-—-지향적-태도에-대한-외재론","link":"#좁은-내용과-넓은-내용-—-지향적-태도에-대한-외재론","children":[]}],"relativePath":"philosophy/Philosophy-of-Mind/08. 지향성.md","filePath":"philosophy/Philosophy-of-Mind/08. 지향성.md"}'),e={name:"philosophy/Philosophy-of-Mind/08. 지향성.md"};function u(l,t,a,i,q,g){return n(),r("div",null,[...t[0]||(t[0]=[s('<h2 id="지향성이란" tabindex="-1">지향성이란 <a class="header-anchor" href="#지향성이란" aria-label="Permalink to &quot;지향성이란&quot;">​</a></h2><p>믿음, 욕구, 생각, 상상 같은 많은 마음 상태는 다른 어떤 것에 &quot;<strong>대한</strong>(about)&quot; 것이고, 그것을 &quot;지향&quot;하며 &quot;<strong>표상</strong>(represent)&quot;한다. 마음 상태의 이런 성격을 <strong>지향성(intentionality)</strong>이라 하고, 이 특성을 갖는 마음 상태를 지향적 마음 상태라 부른다. 이 중세의 용어를 부활시킨 19세기 독일 철학자 <strong>브렌타노(Franz Brentano)</strong>는 이렇게 말한다.</p><blockquote><p>&quot;지향성은 정신적 현상에만 배타적으로 성립하는 특징이다. 어떤 물리적 현상도 그와 같은 것을 보이지 않는다. 그러므로 우리는 정신적 현상을, 지향적으로 어떤 대상을 포함하는 현상이라고 정의할 수 있다.&quot;</p></blockquote><p>이는 두 주장으로 이루어진다 — (A) 지향성은 마음만이 갖는 특징이며 물리적 현상은 지향성을 갖지 않는다, (B) 모든 마음 상태는 지향성을 갖는다. 간단히 말해 지향성이 정신적인 것의 &quot;표지&quot;라는 주장이다.</p><p><strong>(A)는 맞는 주장인가?</strong> 사진, 그림, 지도, 문장 등도 무언가를 표상하지만, 이것들이 본래적으로 지향성을 갖는다고 보기는 어렵다 — 사람이 그렇게 해석하기 때문에 지향성을 갖는 것으로 보는 편이 합당하다(나무의 나이테는 어떤가?). 이 주장이 맞다면, 지향적 마음 상태는 물리적인 것으로 환원될 수 없다는 것이 따라 나온다 — 지향성을 물리적으로 설명하려는 시도는 현대 심리철학의 핵심 문제 중 하나다.</p><p><strong>(B)는 맞는 주장인가?</strong> 신체적 감각이나 고통, 우울함 같은 감정은 어떤가? 특히 <strong>감각질(qualia)</strong>의 경우, 경험도 지향성을 갖는다고 볼 수는 있지만 지향성이 경험의 질적인 특성까지 온전히 포착하는지는 많은 철학자들이 의심한다.</p><h2 id="지향성의-역설" tabindex="-1">지향성의 역설 <a class="header-anchor" href="#지향성의-역설" aria-label="Permalink to &quot;지향성의 역설&quot;">​</a></h2><p>지향성이 신비로운 현상으로 여겨지는 이유 중 하나는 다음과 같은 두 역설 때문이다.</p><ol><li><strong>존재하지 않는 대상에 대한 지향</strong>: 지향성은 마음 상태가 어떤 대상과 맺는 관계여야 하는데, 그 대상이 아예 존재하지 않을 수도 있다. 진시황이 불로초를 원하지만 불로초는 존재하지 않는다면, 진시황이 원하는 &quot;그것&quot;은 대체 무엇인가? (이 역설 때문에 마이농(Meinong)은 아예 &quot;존재하지 않는 대상&quot;이 있다고 주장하기도 했다.)</li><li><strong>동일 대상에 대한 태도의 불일치</strong>: 마음 상태가 어떤 대상과 지향적 관계를 맺는 동시에 맺지 않을 수 있다. 나는 (이 수업을 듣는) 철수와 사귀길 원하지만, 이 수업에서 학점이 가장 낮은 사람과 사귀길 원하지는 않는다. 그런데 철수 = 이 수업에서 학점이 가장 낮은 사람이라면, 어떻게 이것이 가능한가?</li></ol><p>많은 현대 철학자들은 지향성을 주체가 구체적 <strong>대상</strong>과 맺는 관계가 아니라, 주체와 <strong>명제(proposition)</strong> 사이의 관계로 봄으로써 이 역설을 해소한다.</p><h2 id="명제적-태도" tabindex="-1">명제적 태도 <a class="header-anchor" href="#명제적-태도" aria-label="Permalink to &quot;명제적 태도&quot;">​</a></h2><p><strong>명제적 태도(propositional attitude)</strong>란 영어의 &quot;that-절&quot;로 표현될 수 있는 마음 상태를 말한다 — &quot;[어린아이들은 깜찍한 데가 있다]고 생각한다&quot;, &quot;[인간은 커다란 잠재력을 갖고 있다]고 믿는다&quot; 등. 여기서 <strong>명제</strong>란 참·거짓을 갖는 평서문이 의미하는 바, 즉 수(數)와 같은 <strong>추상적 대상</strong>으로 여겨진다. 철학자들은 명제적 태도가 갖는 명제를 <strong>심적 내용(mental content)</strong>이라 부르기도 한다.</p><p>대부분(혹은 모든) 지향적 마음 상태는 이런 명제적 태도로 재구성될 수 있다 — &quot;진시황이 불로초를 원한다&quot;는 &quot;진시황은 [자신이 불로초를 구하기를] 원한다&quot;로 바꿔 쓸 수 있다. 이렇게 재구성하면 앞의 역설도 해소된다.</p><ol><li>불로초가 존재하지 않아도 &quot;진시황이 불로초를 구하다&quot;라는 <strong>명제</strong>는 (거짓이지만) 여전히 존재한다.</li><li>철수 = 이 수업에서 학점이 가장 낮은 사람이더라도, &quot;내가 철수와 사귄다&quot;와 &quot;내가 이 수업에서 학점이 가장 낮은 사람과 사귄다&quot;는 서로 다른 명제이므로, 하나는 원하면서 다른 하나는 원하지 않는 것이 가능하다.</li></ol><p>의심하다, 희망하다, 추리하다, 가정하다, 놀라다 등 P라는 명제를 대상으로 갖는 태도들은 모두 이런 식으로 이해되며, 이 명제 태도들이 통속심리학의 핵심을 이룬다.</p><h2 id="명제적-태도와-수적-태도-—-신비감의-완화" tabindex="-1">명제적 태도와 &quot;수적 태도&quot; — 신비감의 완화 <a class="header-anchor" href="#명제적-태도와-수적-태도-—-신비감의-완화" aria-label="Permalink to &quot;명제적 태도와 &quot;수적 태도&quot; — 신비감의 완화&quot;">​</a></h2><p>명제적 태도는 여전히 신비롭다 — 어떻게 사람의 상태가 추상적 대상(명제)과 관련을 맺을 수 있는가? 처치랜드를 비롯한 철학자들은 <strong>수(數)</strong>와의 비유로 이 신비감을 완화하려 한다.</p><p>물리학이 &quot;100km의 속도&quot;, &quot;70kg의 무게&quot;처럼 <strong>수적 태도</strong>를 통해 물리적 대상을 기술하듯, 통속심리학은 <strong>명제 태도</strong>를 통해 마음 상태를 기술한다는 것이다. &quot;n보다 2배 크다&quot;는 수들 사이의 관계가 &quot;내 몸무게는 네 몸무게보다 2배 더 나간다&quot;는 수적 태도들 사이의 관계를 특징짓듯, 명제들 사이의 논리적 관계(부정합성, 함축관계 등)가 명제 태도들 사이의 관계(예: &quot;내 믿음은 네 믿음과 정합적이지 못하다&quot;)를 특징짓는다는 구조적 유사성이 있다는 것.</p><p>핵심 논점: 수나 벡터를 이용한다고 해서 어떤 이론이 본질적으로 물질적이거나 비물질적인 것은 아니듯, 명제(추상적 대상)를 이용해 마음 상태를 기술한다고 해서 그 이론이 곧바로 물질적이거나 비물질적인 것으로 결정되지는 않는다. 명제 태도가 궁극적으로 물질적 본성을 갖느냐는 경험적 문제로 남는다 — 예컨대 &quot;x가 P를 믿고 P이면 Q라는 것도 믿는다면, 혼란이 없는 한 x는 Q도 믿게 될 것이다&quot; 같은 통속심리학 원리는 명제들 사이의 논리적 관계로 표현될 수 있다.</p><p>이런 견해는 지향적 마음 상태에 대한 신비감을 상당히 완화시켜 주지만, 모든 문제를 해결하지는 않는다 — 마음을 가진 존재의 어떤 점이 이런 식의 기술을 애초에 가능하게 하는지는 여전히 풀어야 할 문제로 남는다.</p><h2 id="사유의-언어-가설-포더" tabindex="-1">사유의 언어 가설 (포더) <a class="header-anchor" href="#사유의-언어-가설-포더" aria-label="Permalink to &quot;사유의 언어 가설 (포더)&quot;">​</a></h2><p>마음 상태가 어떻게 특정한 명제적 <strong>내용</strong>을 갖는가, 그리고 그러기 위해 두뇌가 어떤 구조를 가져야 하는가는 여전히 답이 필요한 물음이다. 한쪽 극단에 있는 영향력 있는 답이 <strong>제리 포더(Jerry Fodor)</strong>의 <strong>사유의 언어 가설(Language of Thought, LOT Hypothesis)</strong>이다.</p><p>이는 두 주장으로 구성된다.</p><ol><li>두뇌 안에 &quot;단어&quot;에 해당하는 표상들이 있고, 이들이 순전히 구문론적으로 조합되어 &quot;문장&quot;이 되며, 이 문장이 명제를 표현한다. 단어들은 세계와의 인과관계를 통해 의미를 갖는다.</li><li>이렇게 구성된 문장이 믿음이 되는지 욕구가 되는지는 그 문장이 수행하는 기능적 역할에 따라 결정된다 — &quot;<strong>믿음박스</strong>&quot;의 비유: 정신적 언어의 문장이 &quot;믿음박스&quot;에 들어 있으면 믿음이고, &quot;욕구박스&quot;에 들어 있으면 욕구다.</li></ol><p>포더가 이 가설을 지지하는 두 근거는 다음과 같다.</p><ul><li><strong>사고의 체계성(systematicity)</strong>: &quot;철수가 영희를 사랑한다&quot;를 생각할 수 있는 사람은 &quot;영희가 철수를 사랑한다&quot;도 생각할 수 있다 — 생각이 언어적 구조를 갖는다고 가정하면 이것이 잘 설명된다.</li><li><strong>사고의 생산성(productivity)</strong>: 단어를 이해하는 사람은 그로부터 구성된 새로운 문장도 이해할 수 있듯, 사람은 거의 무한히 많은 새로운 생각을 구성할 수 있다 — 역시 생각의 언어적 구조 가정으로 잘 설명된다.</li></ul><p>이와 대조적으로 다른 쪽 극단에는, 명제적 태도를 실현하는 물리적 상태가 굳이 특정한 (언어 유사) 구조를 가질 필요가 없다는 입장이 있다 — 다음의 데닛이 그 대표적 사례다.</p><h2 id="데닛의-세-가지-예측-전략과-지향적-태도" tabindex="-1">데닛의 세 가지 예측 전략과 지향적 태도 <a class="header-anchor" href="#데닛의-세-가지-예측-전략과-지향적-태도" aria-label="Permalink to &quot;데닛의 세 가지 예측 전략과 지향적 태도&quot;">​</a></h2><p><strong>대니얼 데닛(Daniel Dennett)</strong>은 어떤 대상의 행동을 예측하는 세 전략을 구분한다.</p><table tabindex="0"><thead><tr><th>전략</th><th>방법</th><th>예시</th></tr></thead><tbody><tr><td><strong>물리적 태도(physical stance)</strong></td><td>물리법칙과 물리적 구성에 대한 지식을 총동원해 예측</td><td>손에서 놓은 돌멩이가 떨어질 것이라는 예측 — 생물도 인공물도 아닌 모든 대상에 유일하게 가능한 전략</td></tr><tr><td><strong>설계적 태도(design stance)</strong></td><td>대상이 특정 목적으로 &quot;설계&quot;되었다고 가정하고 그 설계대로 행동할 것이라 예측</td><td>정확성은 떨어지지만(오작동 가능성 배제 못함), 인공물의 행동을 설명하는 유일한 실용적 방법인 경우가 많음</td></tr><tr><td><strong>지향적 태도(intentional stance)</strong></td><td>대상이 스스로의 &quot;믿음&quot;과 &quot;욕구&quot;를 &quot;고려&quot;해 &quot;선택&quot;하는 합리적 행위자인 것처럼 대하는 전략</td><td>체스 컴퓨터, 동물, 심지어 온도조절장치까지 이런 식으로 이해 가능</td></tr></tbody></table><p>체스 두는 컴퓨터의 수를 예측할 때, 물리적 태도(회로 단위 시뮬레이션)와 설계적 태도(소스코드 분석)는 계산 복잡성 때문에 실천적으로 불가능하지만, 지향적 태도(&quot;이 컴퓨터는 최선의 수를 두려 할 것이다&quot;)는 실패 확률이 있음에도 가장 손쉽게 예측을 가능케 한다.</p><p>인간 행동의 예측·설명에서 지향적 태도는 거의 불가결하다 — &quot;우리는 서로를 지향적 체계로 대할 때, 서로의(그리고 자신의!) 두개골 속에서 무슨 일이 일어나는지 시시콜콜 알 필요가 없다. 우리는 사람이 합리적이라고 짐작하면 얼추 맞는다는 사실에 무의식적으로 의존한다.&quot; 데닛은 이런 지향적 태도 취하기 능력이 언어 능력처럼 타고난 생성적(generative) 능력이라고 본다.</p><h2 id="지향적-체계로서의-마음-—-도구주의-논쟁" tabindex="-1">지향적 체계로서의 마음 — 도구주의 논쟁 <a class="header-anchor" href="#지향적-체계로서의-마음-—-도구주의-논쟁" aria-label="Permalink to &quot;지향적 체계로서의 마음 — 도구주의 논쟁&quot;">​</a></h2><p>데닛은 &quot;어떤 대상에 대해 지향적 태도를 취함으로써 그 행동을 유용하게 예측할 수 있다면, 그 대상은 정의상 <strong>지향적 체계(intentional system)</strong>&quot;라고 정의한다. 여기서 더 나아가, 우리가 명제 태도를 가진다는 것은 우리가 이런 의미에서 지향적 체계라는 것 그 이상이 아니라고 주장한다 — 즉 믿음·욕구를 가지려면 사유의 언어 가설이 요구하는 것과 같은 특정한 내적 구조를 가져야 하는 것이 아니라는 것.</p><p><strong>반론</strong>: 백합, 나무, 심지어 책상의 행동도 지향적 태도로 예측 가능해 보인다. 하지만 이는 단순한 &quot;의인화&quot;에 불과하다는 강한 직관이 있다 — 이런 것들은 사고를 갖기에 적합한 내적 구조를 결여하기 때문 아닌가? 데닛은 지향적 태도가 &quot;얼마나 유용하냐&quot;가 중요하며, 나무의 경우엔 그다지 유용하지 않다고 응수한다. 그러나 &quot;유용성&quot;은 모호한 개념이어서, 어디서부터 진짜로 믿음을 갖는 대상인지는 결국 모호하게 남는다.</p><p>또 다른 반론: 엄청난 지적 능력을 가진 외계인이 물리적 태도만으로 인간 행동을 완전한 정확성으로 예측할 수 있다면, 그 외계인에게는 지향적 태도가 전혀 유용하지 않을 것이다 — 그렇다면 어떤 대상이 지향적 마음 상태를 갖느냐는 관점에 따라 상대적인 것이 되어버리는 것 아닌가? 데닛은 지향적 태도의 &quot;성공 여부&quot;는 여전히 객관적이라고 항변하지만, 이런 이유로 그의 견해는 (본인의 부인에도 불구하고) 종종 지향적 마음 상태에 대한 <strong>도구주의(instrumentalism)</strong>로, 또 모종의 행동주의를 함축하는 입장으로 간주된다.</p><h2 id="좁은-내용과-넓은-내용-—-지향적-태도에-대한-외재론" tabindex="-1">좁은 내용과 넓은 내용 — 지향적 태도에 대한 외재론 <a class="header-anchor" href="#좁은-내용과-넓은-내용-—-지향적-태도에-대한-외재론" aria-label="Permalink to &quot;좁은 내용과 넓은 내용 — 지향적 태도에 대한 외재론&quot;">​</a></h2><p>전통적으로 믿음·욕구 같은 마음 상태는 당연히 내 &quot;안&quot;에 있는 어떤 것으로 여겨져 왔다 — 즉 두 사람이 완전히 동일한 내적 상태에 있다면 그들의 믿음도 필연적으로 동일하다는 <strong>수반(supervenience)</strong> 관계가 성립한다고 가정되었다. 그러나 1970년대 <strong>퍼트남(Putnam)</strong>과 <strong>버지(Burge)</strong>의 사고실험은 이 상식에 도전한다 — 이를 심적 내용에 관한 <strong>외재론(externalism)</strong>이라 부른다.</p><p><strong>간단한 사유실험</strong>: 피터와 메리가 각각 매우 유사한(그러나 서로 다른) 토마토를 보며 똑같이 &quot;이 토마토는 상했다&quot;고 생각한다. 내부 관점(신경 상태 포함)에서는 완전히 동일하지만, 두 사람의 믿음의 <strong>내용</strong>은 서로 다른 대상(각자가 보고 있는 그 토마토)에 관한 것이므로 명백히 다르다. 즉 동일한 내적 상태에 있으면서도 다른 믿음을 가지므로, 이런 믿음은 내적 상태에 수반하지 않는다.</p><p><strong>쌍둥이지구(Twin Earth) 사유실험</strong>: 지구와 모든 면에서 똑같지만 딱 한 가지, 물처럼 보이고 물처럼 행동하는(투명하고 갈증을 풀어주고 0도에서 어는) 물질이 H₂O가 아니라 <strong>XYZ</strong>라는 별개의 분자 구조로 되어 있는 행성을 상상하자. 쌍둥이지구인은 지구인과 똑같이 &quot;물&quot;이라는 단어를 쓰지만, 그들이 마시는 것은 H₂O가 아니라 XYZ다.</p><ul><li>지구인이 &quot;나는 물을 마시고 싶다&quot;고 말하면, 그의 &quot;물&quot;은 H₂O를 외연으로 갖는다.</li><li>쌍둥이지구인이 똑같은 말을 하면, 그의 &quot;물&quot;은 XYZ를 외연으로 갖는다(제대로 번역하려면 &quot;쿨(twater)&quot; 같은 새 단어가 필요하다).</li></ul><p>지구인과 쌍둥이지구인은 (지구를 떠난 적 없다는 가정하에) 완전히 동일한 내적 상태에 있으면서도 서로 다른 욕구(물에 대한 욕구 vs. 쿨에 대한 욕구)를 갖는다 — 이는 욕구가 내적 상태에 수반한다는 통념을 반박한다. 즉 믿음이나 욕구는 전적으로 사람 &quot;안&quot;에 존재하는 것이 아니라는 결론이 따라 나온다.</p><p><strong>추가 사유실험 — 시간에 따른 내용 변화</strong>:</p><ol><li>지구인이 (자신도 모르게) 쌍둥이지구로 옮겨진 직후 호수를 보며 &quot;호수에 물이 가득하군&quot;이라고 말한다면? — 직관적으로 이는 <strong>물</strong>에 대한 믿음이다.</li><li>그가 이 사실을 모른 채 쌍둥이지구에서 수십 년을 살고 나서 같은 말을 한다면? — 직관적으로 이는 이제 <strong>쿨</strong>에 대한 믿음이다.</li></ol><p>이는 환경과의 <strong>지속적인 인과적 상호작용</strong>이 명제적 태도의 내용에 영향을 미침을 시사한다 — &quot;당신이 어떤 구체적 믿음을 갖는지는 현재는 물론 과거에 대한, 그리고 당신 안에서 일어나는 일은 물론 주변 환경의 대상·사건에 대한 관계에 의존한다.&quot; 이처럼 마음 상태의 내용 중 환경(외부 세계와의 관계)에 의해 결정되는 부분을 <strong>넓은 내용(wide content)</strong>, 순전히 내적 상태만으로 결정되는(수반하는) 부분을 <strong>좁은 내용(narrow content)</strong>이라 부른다. 이 사고실험들이 보여주는 것은 넓은 내용이 실제로 존재한다는 것이다.</p>',45)])])}const d=o(e,[["render",u]]);export{h as __pageData,d as default};
